insert into process_maps (id, org_id, title, status) values
  ('10000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000001', 'Loan file completeness', 'draft')
insert into nodes (map_id, id, primitive, label, config, x, y) values
  ('10000000-0000-0000-0000-000000000003', 'ch_intake', 'channel', 'Underwriting inbox', '{"tool":"composio.gmail","match":{"subject_patterns":["Loan file","Borrower documents"]},"describes":"Borrowers and brokers email documents to the underwriting inbox."}'::jsonb, 40, 180),
  ('10000000-0000-0000-0000-000000000003', 'doc_app', 'artifact', 'Application', '{"identity_key":"loan_number","fields":["loan_number","borrower_name","stated_income"],"source_hint":"the form headed ''Uniform Residential Loan Application''","describes":"The loan application form the borrower filled in."}'::jsonb, 280, 100),
  ('10000000-0000-0000-0000-000000000003', 'doc_stub', 'artifact', 'Pay stub', '{"identity_key":"loan_number","fields":["loan_number","employer","gross_pay"],"source_hint":"the payroll document with an employer name and a pay period","describes":"A pay stub proving the income on the application."}'::jsonb, 280, 300),
  ('10000000-0000-0000-0000-000000000003', 'rule_stub', 'policy', 'Application has a pay stub', '{"describes":"Every application on file needs a matching pay stub.","check":{"relation":"exists_matching","params":{"on":"loan_number"}},"reads":["doc_app.loan_number","doc_stub.loan_number"],"verdict_on":"doc_app","on_fail":"flag_and_continue","on_absent":"fail","confirmed_by":"c_02"}'::jsonb, 560, 260),
  ('10000000-0000-0000-0000-000000000003', 'rule_income', 'policy', 'Income is stated', '{"describes":"The borrower has to have put an income on the application.","check":{"relation":"present"},"reads":["doc_app.stated_income"],"verdict_on":"doc_app","on_fail":"flag_and_continue","on_absent":"fail","confirmed_by":"c_03"}'::jsonb, 560, 80),
  ('10000000-0000-0000-0000-000000000003', 'out_file', 'output', 'File review result', '{"rows":[{"label":"files_reviewed","fn":"count","of":"doc_app"},{"label":"files_complete","fn":"count","of":"doc_app","where":"pass"},{"label":"files_incomplete","fn":"count","of":"doc_app","where":"fail"},{"label":"incomplete_ids","fn":"list","of":"doc_app.loan_number","where":"fail"}],"describes":"How many files we reviewed and which are still incomplete."}'::jsonb, 820, 160)
insert into edges (map_id, id, from_node, to_node, config) values
  ('10000000-0000-0000-0000-000000000003', 'l1', 'ch_intake', 'doc_app', '{"cardinality":"many"}'::jsonb),
  ('10000000-0000-0000-0000-000000000003', 'l2', 'ch_intake', 'doc_stub', '{"cardinality":"many"}'::jsonb),
  ('10000000-0000-0000-0000-000000000003', 'l3', 'doc_app', 'doc_stub', '{"rel":"pairs_with","on":"loan_number"}'::jsonb),
  ('10000000-0000-0000-0000-000000000003', 'l4', 'doc_app', 'rule_stub', '{}'::jsonb),
  ('10000000-0000-0000-0000-000000000003', 'l5', 'doc_stub', 'rule_stub', '{}'::jsonb),
  ('10000000-0000-0000-0000-000000000003', 'l6', 'doc_app', 'rule_income', '{}'::jsonb),
  ('10000000-0000-0000-0000-000000000003', 'l7', 'rule_stub', 'out_file', '{}'::jsonb),
  ('10000000-0000-0000-0000-000000000003', 'l8', 'rule_income', 'out_file', '{}'::jsonb)
