insert into nodes (map_id, id, primitive, label, config, x, y) values
  ('10000000-0000-0000-0000-000000000002', 'ch_a1', 'channel', 'Pre-alert inbox', '{"tool":"composio.gmail","match":{"subject_patterns":["Pre-Alert Documents"]},"describes":"Freight forwarders email us the paperwork before a container lands."}'::jsonb, 40, 200),
  ('10000000-0000-0000-0000-000000000002', 'rec_inv', 'artifact', 'Commercial invoice', '{"identity_key":"invoice_number","fields":["invoice_number","container_no"],"source_hint":"attachment headed ''Commercial Invoice''","describes":"The commercial invoice for a shipment. It comes in as an attachment on the pre-alert."}'::jsonb, 260, 120),
  ('10000000-0000-0000-0000-000000000002', 'rec_good', 'artifact', 'Good', '{"fields":["hts","fda_product_code","anda","reg_no","ndc"],"describes":"A line item on the invoice — one product, with its regulatory codes."}'::jsonb, 480, 40),
  ('10000000-0000-0000-0000-000000000002', 'rec_batch', 'artifact', 'Batch', '{"identity_key":"batch_number","fields":["batch_number"],"describes":"A manufacturing batch listed against a line item."}'::jsonb, 480, 200),
  ('10000000-0000-0000-0000-000000000002', 'rec_coa', 'artifact', 'Certificate of analysis', '{"identity_key":"batch_number","fields":["batch_number"],"source_hint":"attachment headed ''Certificate of Analysis''","describes":"The lab certificate for a batch, attached to the same email."}'::jsonb, 480, 320),
  ('10000000-0000-0000-0000-000000000002', 'rule_fields', 'policy', 'Required codes present', '{"describes":"Each good has to carry all five regulatory codes.","check":{"relation":"present"},"reads":["rec_good.hts","rec_good.fda_product_code","rec_good.anda","rec_good.reg_no","rec_good.ndc"],"verdict_on":"rec_good","on_fail":"flag_and_continue","on_absent":"fail","confirmed_by":"c_04"}'::jsonb, 720, 40),
  ('10000000-0000-0000-0000-000000000002', 'rule_coa', 'policy', 'Batch has certificate', '{"describes":"Every batch on the invoice needs a certificate of analysis.","check":{"relation":"exists_matching","params":{"on":"batch_number"}},"reads":["rec_batch.batch_number","rec_coa.batch_number"],"verdict_on":"rec_batch","on_fail":"flag_and_continue","on_absent":"fail","confirmed_by":"c_07"}'::jsonb, 720, 260),
  ('10000000-0000-0000-0000-000000000002', 'ch_out', 'channel', 'Discrepancy email', '{"tool":"composio.gmail","request":{"to":"danieljhsiao@gmail.com","subject":"Discrepancy — invoice {rec_inv.invoice_number}","body":"Missing certificates for: {rec_batch.batch_number where fail}"},"describes":"We email the forwarder about anything missing and wait for them to send it."}'::jsonb, 960, 380),
  ('10000000-0000-0000-0000-000000000002', 'out_res', 'output', 'Shipment result', '{"rows":[{"label":"invoices_processed","fn":"count","of":"rec_inv"},{"label":"invoices_failed","fn":"count","of":"rec_inv","where":"fail"},{"label":"goods_failed","fn":"count","of":"rec_good","where":"fail"},{"label":"batches_processed","fn":"count","of":"rec_batch"},{"label":"batches_failed","fn":"count","of":"rec_batch","where":"fail"},{"label":"failed_batch_ids","fn":"list","of":"rec_batch.batch_number","where":"fail"}],"describes":"How many invoices and batches we processed, and which ones failed."}'::jsonb, 960, 140)
